# A tiny SCIM 2.0 endpoint: the IdP creates, updates and deactivates users
from fastapi import FastAPI, Header, HTTPException
from fastapi.testclient import TestClient

app = FastAPI()
USERS = {}                                   # your real app uses its database
SCIM_TOKEN = "scim-demo-token"               # a long random secret in real life

def auth(authorization: str):
    if authorization != f"Bearer {SCIM_TOKEN}":
        raise HTTPException(401)

@app.post("/scim/v2/Users", status_code=201)
def create_user(body: dict, authorization: str = Header("")):
    auth(authorization)
    uid = f"u{len(USERS) + 1}"
    USERS[uid] = {"userName": body["userName"], "active": body.get("active", True)}
    return {"schemas": ["urn:ietf:params:scim:schemas:core:2.0:User"],
            "id": uid, **USERS[uid]}

@app.patch("/scim/v2/Users/{uid}")
def patch_user(uid: str, body: dict, authorization: str = Header("")):
    auth(authorization)
    for op in body["Operations"]:
        if op.get("path") == "active":
            USERS[uid]["active"] = op["value"]
            if op["value"] is False:
                end_all_sessions(uid)        # offboarding must cut access now
    return {"id": uid, **USERS[uid]}

def end_all_sessions(uid):
    print("sessions and refresh tokens revoked for", uid)

c = TestClient(app)
h = {"Authorization": f"Bearer {SCIM_TOKEN}"}
r = c.post("/scim/v2/Users", json={"userName": "dana@fernhollow.com"}, headers=h)
print(r.status_code, r.json()["id"])         # 201 u1
r = c.patch("/scim/v2/Users/u1", headers=h, json={
    "schemas": ["urn:ietf:params:scim:api:messages:2.0:PatchOp"],
    "Operations": [{"op": "replace", "path": "active", "value": False}]})
# sessions and refresh tokens revoked for u1
print(r.json())       # {'id': 'u1', 'userName': 'dana@fernhollow.com', 'active': False}

# Map IdP groups (Entra ID sends group object ids) to app roles
GROUP_TO_ROLE = {                      # agreed in writing with the customer's IT team
    "4f1c2a7e-0b1d-4c55-9a0e-2d9f6c1b7a10": "adjuster",
    "9b8e7d6c-5a4f-4e3d-8c2b-1a0f9e8d7c6b": "viewer",
}

def roles_from_claims(claims: dict) -> set:
    if "_claim_names" in claims and "groups" in claims["_claim_names"]:
        # Too many groups for the token (group overage): fetch them from
        # Microsoft Graph instead of trusting an empty list.
        raise LookupError("group overage: call Graph /me/transitiveMemberOf")
    if claims.get("roles"):            # Entra app roles: already role names
        return set(claims["roles"])
    return {GROUP_TO_ROLE[g] for g in claims.get("groups", []) if g in GROUP_TO_ROLE}

print(roles_from_claims({"groups": ["4f1c2a7e-0b1d-4c55-9a0e-2d9f6c1b7a10", "other"]}))
# {'adjuster'}
print(roles_from_claims({"roles": ["Claims.Approver"]}))   # {'Claims.Approver'}
print(roles_from_claims({"groups": []}))                  # set()  (no role: deny)

