# SSRF defence for a "fetch this URL" feature: allowlist, check every IP,
# and re-check after every redirect instead of letting the library follow it.
import ipaddress, socket
from urllib.parse import urlparse
import httpx

ALLOWED_HOSTS = {"docs.fernhollow.com", "files.fernhollow.com"}

def resolve_ips(host):
    return {ai[4][0] for ai in socket.getaddrinfo(host, None)}

def check_url(url):
    u = urlparse(url)
    if u.scheme not in {"http", "https"} or u.hostname not in ALLOWED_HOSTS:
        raise ValueError(f"host not allowed: {u.hostname}")
    for ip in resolve_ips(u.hostname):
        a = ipaddress.ip_address(ip)
        if a.is_private or a.is_loopback or a.is_link_local or a.is_reserved:
            raise ValueError(f"{u.hostname} resolves to internal {ip}")

def safe_get(url, client, max_hops=3):
    for _ in range(max_hops + 1):
        check_url(url)                                     # check EVERY hop
        r = client.get(url, follow_redirects=False)
        if r.status_code in (301, 302, 303, 307, 308):
            url = str(r.url.join(r.headers["location"]))   # next hop, re-checked
            continue
        return r
    raise ValueError("too many redirects")

# Offline demo: a fake network where an allowed host redirects to the
