FAKE_DNS = {"docs.fernhollow.com": {"151.101.1.10"},
            "files.fernhollow.com": {"10.0.0.7"}}      # private: DNS points inside
resolve_ips = lambda host: FAKE_DNS.get(host) or {host}

def handler(request):
    if request.url.path == "/ok":
        return httpx.Response(200, text="report text")
    return httpx.Response(302, headers={"location": "http://169.254.169.254/latest/meta-data/"})

client = httpx.Client(transport=httpx.MockTransport(handler))
print(safe_get("https://docs.fernhollow.com/ok", client).text)   # report text
for url in ["https://docs.fernhollow.com/go",      # redirect to metadata IP
            "https://files.fernhollow.com/a",      # allowed name, private IP
            "http://localhost:8080/admin"]:        # not on the allowlist
    try:
        safe_get(url, client)
    except ValueError as e:
