import json, random, time
import redis   # pip install redis; fakeredis works the same for tests

r = redis.Redis(host="localhost", port=6379, decode_responses=True)
# In a test: import fakeredis; r = fakeredis.FakeRedis(decode_responses=True)

MISSING = "__none__"                      # marker for negative caching

def cache_get_or_load(key: str, loader, ttl: int = 300, miss_ttl: int = 30):
    value = r.get(key)
    if value is not None:                         # hit (maybe a cached "not found")
        return None if value == MISSING else json.loads(value)
    # Stampede protection: only one caller rebuilds, the others wait briefly
    lock = r.set(f"lock:{key}", "1", nx=True, ex=10)   # SET key NX EX 10
    if not lock:
        for _ in range(50):                       # wait up to 5 s for the winner
            time.sleep(0.1)
            value = r.get(key)
            if value is not None:
                return None if value == MISSING else json.loads(value)
    try:
        value = loader()                          # miss: read source
        if value is None:                         # negative cache "not found"
            r.set(key, MISSING, ex=miss_ttl)
        else:
            jitter = random.randint(0, ttl // 10) # spread expiry times
            r.set(key, json.dumps(value), ex=ttl + jitter)
        return value
    finally:
        if lock:
            r.delete(f"lock:{key}")

def product_key(tenant: str, product_id: int, scope: str = "public", ver: str = "v4"):
    # tenant + permission scope + version in every key: no cross-tenant leaks
    return f"t:{tenant}:{scope}:product:{product_id}:{ver}"

