// pricing.proto
syntax = "proto3";

package pricing.v1;              // version lives in the package name

service Pricing {
  rpc Quote (QuoteRequest) returns (QuoteReply);
}

message QuoteRequest {
  string origin_postcode = 1;     // field numbers identify fields on the wire
  string dest_postcode   = 2;
  double weight_kg       = 3;
}

message QuoteReply {
  int64  price_cents = 1;
  string currency    = 2;
}
// Generate Python code:
