// Safe evolution: add new numbers, reserve removed ones, never renumber
message QuoteRequestV2Example {
  reserved 4;                       // old weight_lbs: number can never be reused
  reserved "weight_lbs";
  string origin_postcode = 1;
  string dest_postcode   = 2;
  double weight_kg       = 3;
  string service_level   = 5;       // new optional field: old clients ignore it
}
